      SUBROUTINE UPDAT2CC     UPDATE AUXILLIARY TRANSFER MATRIX R2CC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'R2VT.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'      DIMENSION RCVS(6,6), RCVSL(36)      EQUIVALENCE (RCVS(1,1),RCVSL(1))C      IF (R3P) CALL UPDAT3      IF (NORD2 .LT. 1) GO TO 280CC     BEAM UPDATEC      IF (NORD3 .GE. 1) CALL UPSIGCC     PARTIAL DERIVATIVES OF ACCUMULATED R MATRIXC   15 IF (NV1 .LT. 1) GO TO 200      DO 190 N = 1, NV1CC     R2 TIMES DERIVATIVE OF R1C      IF (.NOT. RVP(N)) GO TO 100      DO 40 JK = 1, 36      RCVSL(JK) = RCVL(JK,N)    40 CONTINUE      CALL CAB(RS,RC2,RCVS)   45 DO 50 JK = 1, 36   50 RCVL(JK,N) = RSL(JK)CC     DERIVATIVE OF R2 TIMES R1C  100 IF (RCP) GO TO 130      DO 110 JK = 1, 36  110 RCVL(JK,N) = R2VL(JK,N)      GO TO 180C  130 IF (.NOT. R2VP(N)) GO TO 180      DO 140 JK = 1, 36  140 R2VTL(JK) = R2VL(JK,N)      CALL CAB(RS,R2VT,RC)      IF (.NOT. RVP(N)) THEN        DO 150 JK = 1, 36  150   RCVL(JK,N) = RSL(JK)      ELSEC        DO 160 JK = 1, 36  160   RCVL(JK,N) = RCVL(JK,N) + RSL(JK)      ENDIF  180 CONTINUE      RVP(N) = RVP(N) .OR. R2VP(N)      R2VP(N) = .FALSE.  190 CONTINUECC     ACCUMULATED RC  200 CALL MR2RC      CALL RSTORC  280 RCP = RCP .OR. R2P      R2P = .FALSE.      OCP(3) = .FALSE.      RETURN      END